INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Sind Notebooks eine wichtige Geräteklasse in der Hardware?', 2, '[{"text": "Ja", "correct": true, "because": "Mobil und vielseitig"}, {"text": "Nein", "correct": false, "because": "Sie sind relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Hauptmerkmal unterscheidet Notebooks von anderen Geräten?', 3, '[{"text": "Portabilität und integrierte Komponenten", "correct": true, "because": "Mobil einsetzbar"}, {"text": "Hohe Rechenleistung", "correct": false, "because": "Nicht exklusiv"}, {"text": "Externer Monitor", "correct": false, "because": "Nicht integriert"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Notebooks haben eine integrierte Stromversorgung. b) Sie sind immer leistungsstärker als Desktops.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, oft schwächer"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist zutreffend"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Komponenten gehören typischerweise zu einem Notebook?', 4, '[{"text": "Bildschirm", "correct": true, "because": "Integriertes Display"}, {"text": "Externe Tastatur", "correct": false, "because": "Nicht integriert"}, {"text": "Akku", "correct": true, "because": "Ermöglicht Mobilität"}, {"text": "Prozessor", "correct": true, "because": "Rechenleistung"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein Notebook ohne Akku betrieben werden?', 2, '[{"text": "Ja", "correct": true, "because": "Mit Netzteil möglich"}, {"text": "Nein", "correct": false, "because": "Flexibel einsetzbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielen Notebooks in der IT?', 3, '[{"text": "Mobile Arbeitsgeräte", "correct": true, "because": "Flexibel nutzbar"}, {"text": "Server für Netzwerke", "correct": false, "because": "Andere Geräteklasse"}, {"text": "Nur Gaming", "correct": false, "because": "Breitere Nutzung"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind Notebooks nur für private Nutzung geeignet?', 2, '[{"text": "Nein", "correct": true, "because": "Auch beruflich genutzt"}, {"text": "Ja", "correct": false, "because": "Vielseitig einsetzbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aufgabe hat die GPU in einem Notebook?', 3, '[{"text": "Grafikverarbeitung", "correct": true, "because": "Rendert Bilder"}, {"text": "Daten speichern", "correct": false, "because": "Festplattenaufgabe"}, {"text": "Netzwerkverbindung", "correct": false, "because": "Netzwerkkartenaufgabe"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Notebooks haben eine integrierte Tastatur. b) Sie sind nicht aufrüstbar.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, oft aufrüstbar"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist zutreffend"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was passiert ohne Akku in einem Notebook?', 3, '[{"text": "Betrieb nur mit Netzteil möglich", "correct": true, "because": "Keine Mobilität"}, {"text": "Notebook wird schneller", "correct": false, "because": "Kein Zusammenhang"}, {"text": "Kein Start möglich", "correct": false, "because": "Netzteil ausreichend"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein Notebook als Server genutzt werden?', 2, '[{"text": "Ja", "correct": true, "because": "Technisch möglich"}, {"text": "Nein", "correct": false, "because": "Nicht optimal"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Beispiel zeigt eine Notebook-Komponente?', 3, '[{"text": "SSD für Speicher", "correct": true, "because": "Konkret und real"}, {"text": "Externer Drucker", "correct": false, "because": "Nicht integriert"}, {"text": "Irgendwas", "correct": false, "because": "Zu vage"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist ein Notebook nur für mobile Nutzung geeignet?', 2, '[{"text": "Nein", "correct": true, "because": "Auch stationär nutzbar"}, {"text": "Ja", "correct": false, "because": "Flexibel einsetzbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Merkmale hat ein typisches Notebook?', 4, '[{"text": "Integriertes Display", "correct": true, "because": "Teil des Designs"}, {"text": "Externe Stromversorgung", "correct": false, "because": "Akku integriert"}, {"text": "Tastatur", "correct": true, "because": "Eingabe direkt"}, {"text": "WLAN-Modul", "correct": true, "because": "Netzwerkfähigkeit"}]'),
('00000000-0000-0000-0000-000000000000', 'Muss ein Notebook regelmäßig gewartet werden?', 2, '[{"text": "Ja", "correct": true, "because": "Sichert Langlebigkeit"}, {"text": "Nein", "correct": false, "because": "Wartung hilft"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt RAM in einem Notebook?', 3, '[{"text": "Arbeitsspeicher für Prozesse", "correct": true, "because": "Unterstützt Leistung"}, {"text": "Dauerhafte Speicherung", "correct": false, "because": "Festplattenaufgabe"}, {"text": "Netzwerkverbindung", "correct": false, "because": "Netzwerkkartenaufgabe"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein Notebook ohne Betriebssystem funktionieren?', 2, '[{"text": "Nein", "correct": true, "because": "Software nötig"}, {"text": "Ja", "correct": false, "because": "Unpraktisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Faktor beeinflusst die Notebook-Leistung?', 3, '[{"text": "Prozessorgeschwindigkeit", "correct": true, "because": "Bestimmt Leistung"}, {"text": "Bildschirmgröße", "correct": false, "because": "Kein direkter Einfluss"}, {"text": "Gewicht", "correct": false, "because": "Kein Leistungsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Notebooks haben Touchpads. b) Sie sind nicht netzwerkfähig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, WLAN vorhanden"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist zutreffend"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist ein Nutzen von Notebooks?', 3, '[{"text": "Flexible Arbeitsmöglichkeiten", "correct": true, "because": "Fördert Mobilität"}, {"text": "Maximale Unbeweglichkeit", "correct": false, "because": "Widerspricht Zweck"}, {"text": "Keine Vielseitigkeit", "correct": false, "because": "Fördert Nutzung"}]');
